-- AUTH-DB-034
-- Canonical authorization evaluator, private runtime projections,
-- resource resolver registry, dataset loaders and safe projections.
--
-- Contract:
--   source_contract_sha256 = b428724a67032dfd1238e7537679c0bffcf62deddaff440b191c753506e696b7
--   vento.authorization@1.1.0 = sha256:9e8d1d7452ed5844fa76b9c718e7bb82ae029d6031234b3b6d9a17f22c2a4359
--   resource identity registry = sha256:2f19d2ebabcc87f8a6bb8029da8f87e05ea86c9acb027aec134995d338604bf4
--
-- No AuthorizationDecision is persisted by this migration.
-- No legacy policy is rewired by this migration.
-- No dynamic SQL is derived from caller input.

begin;

do $auth_db_034_preconditions$
begin
  if not exists (
    select 1
    from pg_catalog.pg_roles
    where rolname = 'vento_authorization_owner'
      and not rolcanlogin
      and not rolinherit
      and not rolsuper
      and not rolcreatedb
      and not rolcreaterole
      and not rolreplication
      and not rolbypassrls
  ) then
    raise exception 'AUTH_DB_034_AUTHORIZATION_OWNER_MISSING_OR_INVALID';
  end if;

  if pg_catalog.to_regnamespace('app_private') is null
     or pg_catalog.to_regnamespace('api') is null
     or pg_catalog.to_regnamespace('extensions') is null then
    raise exception 'AUTH_DB_034_REQUIRED_SCHEMA_MISSING';
  end if;

  if pg_catalog.to_regprocedure(
       'app_private.get_access_context(text)'
     ) is null
     or pg_catalog.to_regprocedure(
       'app_private.bump_context_freshness(jsonb)'
     ) is null
     or pg_catalog.to_regprocedure(
       'app_private.resolve_organization_id()'
     ) is null
     or pg_catalog.to_regprocedure(
       'extensions.digest(text,text)'
     ) is null
     or pg_catalog.to_regprocedure(
       'extensions.gen_random_uuid()'
     ) is null then
    raise exception 'AUTH_DB_034_REQUIRED_FOUNDATION_MISSING';
  end if;
end
$auth_db_034_preconditions$;

grant usage, create
on schema app_private, api
to vento_authorization_owner;

grant usage
on schema extensions
to vento_authorization_owner;

grant execute
on function
  extensions.digest(text, text),
  extensions.gen_random_uuid()
to vento_authorization_owner;

-- The authorization owner receives only the exact AccessContext issuer.
set local role vento_access_context_owner;

grant execute
on function app_private.get_access_context(text)
to vento_authorization_owner;

reset role;

set local role vento_authorization_owner;

create table if not exists
  app_private.authorization_contract_releases (
    catalog_id text not null,
    catalog_version text not null,
    authorization_contract_version text not null,
    schema_version text not null,
    manifest_sha256 text not null,
    permission_count integer not null,
    resource_contract_count integer not null,
    contract_source_sha256 text not null,
    identity_registry_sha256 text not null,
    installed_at timestamptz not null default pg_catalog.statement_timestamp(),
    activated_at timestamptz,
    retired_at timestamptz,
    status text not null,
    source_tasks text[] not null default '{}'::text[],
    metadata jsonb not null default '{}'::jsonb,
    constraint pk_authorization_contract_releases
      primary key (catalog_id, catalog_version),
    constraint ck_authorization_contract_release_status
      check (
        status in (
          'INSTALLED',
          'ACTIVE',
          'SUPERSEDED',
          'BLOCKED'
        )
      ),
    constraint ck_authorization_contract_manifest_sha256
      check (
        manifest_sha256 ~ '^sha256:[0-9a-f]{64}$'
      ),
    constraint ck_authorization_contract_source_sha256
      check (
        contract_source_sha256 ~ '^sha256:[0-9a-f]{64}$'
      ),
    constraint ck_authorization_identity_registry_sha256
      check (
        identity_registry_sha256 ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create unique index if not exists
  uq_authorization_contract_release_active
on app_private.authorization_contract_releases (
  catalog_id
)
where status = 'ACTIVE';

create table if not exists
  app_private.authorization_permission_contracts (
    catalog_id text not null,
    catalog_version text not null,
    permission_key text not null,
    app_code text not null,
    status text not null,
    contract_snapshot jsonb not null,
    contract_fingerprint text not null,
    resource_contract_id text not null,
    source_manifest_sha256 text not null,
    installed_at timestamptz not null default pg_catalog.statement_timestamp(),
    constraint pk_authorization_permission_contracts
      primary key (
        catalog_id,
        catalog_version,
        permission_key
      ),
    constraint ck_authorization_permission_contract_status
      check (
        status in (
          'ACTIVE',
          'SUPERSEDED',
          'BLOCKED'
        )
      ),
    constraint ck_authorization_permission_contract_fingerprint
      check (
        contract_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      ),
    constraint ck_authorization_permission_manifest_sha256
      check (
        source_manifest_sha256 ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create index if not exists
  ix_authorization_permission_contract_app
on app_private.authorization_permission_contracts (
  catalog_version,
  app_code,
  permission_key
);

create table if not exists
  app_private.authorization_resource_resolver_registry (
    resource_contract_id text not null,
    resolver_key text not null,
    resolver_version text not null,
    resource_type text not null,
    allowed_request_modes text[] not null,
    owner_domain text not null,
    source_contract_version text not null,
    source_contract_fingerprint text not null,
    resolver_shape_fingerprint text not null,
    status text not null,
    created_at timestamptz not null default pg_catalog.statement_timestamp(),
    updated_at timestamptz not null default pg_catalog.statement_timestamp(),
    constraint pk_authorization_resource_resolver_registry
      primary key (
        resource_contract_id,
        resolver_version
      ),
    constraint ck_authorization_resource_resolver_status
      check (
        status in (
          'ACTIVE',
          'SUPERSEDED',
          'BLOCKED'
        )
      ),
    constraint ck_authorization_resource_resolver_modes
      check (
        pg_catalog.cardinality(
          allowed_request_modes
        ) > 0
        and allowed_request_modes <@
          array[
            'EXISTING_RESOURCE',
            'RESOURCE_DRAFT',
            'COLLECTION',
            'AGGREGATE',
            'BULK',
            'NON_RESOURCE'
          ]::text[]
      ),
    constraint ck_authorization_resource_source_fingerprint
      check (
        source_contract_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      ),
    constraint ck_authorization_resource_shape_fingerprint
      check (
        resolver_shape_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create unique index if not exists
  uq_authorization_resource_resolver_active
on app_private.authorization_resource_resolver_registry (
  resource_contract_id
)
where status = 'ACTIVE';

create table if not exists
  app_private.authorization_dataset_source_registry (
    dataset_key text not null,
    dataset_version text not null,
    source_owner text not null,
    source_schema text not null,
    source_relation text not null,
    source_contract text not null,
    source_shape_fingerprint text not null,
    fingerprint_strategy text not null,
    status text not null,
    created_at timestamptz not null default pg_catalog.statement_timestamp(),
    updated_at timestamptz not null default pg_catalog.statement_timestamp(),
    constraint pk_authorization_dataset_source_registry
      primary key (
        dataset_key,
        dataset_version
      ),
    constraint ck_authorization_dataset_source_status
      check (
        status in (
          'ACTIVE',
          'SUPERSEDED',
          'BLOCKED'
        )
      ),
    constraint ck_authorization_dataset_source_fingerprint
      check (
        source_shape_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create table if not exists
  app_private.authorization_base_role_grants (
    dataset_version text not null,
    grant_id text not null,
    role_code text not null,
    permission_key text not null,
    authorization_mode text not null,
    lane text not null,
    grant_type text not null,
    effect text not null,
    scope_expression text not null,
    condition_expression text not null,
    source_task text not null,
    record_fingerprint text not null,
    constraint pk_authorization_base_role_grants
      primary key (
        dataset_version,
        grant_id
      ),
    constraint ck_authorization_base_grant_lane
      check (lane = 'BASE'),
    constraint ck_authorization_base_grant_effect
      check (effect = 'ALLOW'),
    constraint ck_authorization_base_grant_fingerprint
      check (
        record_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create index if not exists
  ix_authorization_base_role_grant_lookup
on app_private.authorization_base_role_grants (
  dataset_version,
  role_code,
  permission_key
);

create table if not exists
  app_private.authorization_operational_role_grants (
    dataset_version text not null,
    grant_id text not null,
    operational_role_code text not null,
    permission_key text not null,
    authorization_mode text not null,
    lane text not null,
    grant_type text not null,
    effect text not null,
    scope_expression text not null,
    condition_expression text not null,
    source_task text not null,
    record_fingerprint text not null,
    constraint pk_authorization_operational_role_grants
      primary key (
        dataset_version,
        grant_id
      ),
    constraint ck_authorization_operational_grant_lane
      check (lane = 'OPERATIONAL'),
    constraint ck_authorization_operational_grant_effect
      check (effect = 'ALLOW'),
    constraint ck_authorization_operational_grant_fingerprint
      check (
        record_fingerprint ~ '^sha256:[0-9a-f]{64}$'
      )
  );

create index if not exists
  ix_authorization_operational_role_grant_lookup
on app_private.authorization_operational_role_grants (
  dataset_version,
  operational_role_code,
  permission_key
);

create table if not exists
  app_private.authorization_dataset_seed_records (
    record_id text primary key,
    subject_type text not null,
    subject_ref text not null,
    permission_key text,
    lane text not null,
    effect text not null,
    scope_code text,
    valid_from timestamptz,
    valid_until timestamptz,
    reason_code text,
    status text not null default 'ACTIVE',
    source_contract text not null,
    metadata jsonb not null default '{}'::jsonb,
    constraint ck_authorization_seed_subject_type
      check (
        subject_type in (
          'ACTOR'
        )
      ),
    constraint ck_authorization_seed_lane
      check (
        lane in (
          'ALL',
          'BASE',
          'OPERATIONAL'
        )
      ),
    constraint ck_authorization_seed_effect
      check (
        effect in (
          'ALLOW',
          'DENY'
        )
      ),
    constraint ck_authorization_seed_status
      check (
        status in (
          'ACTIVE',
          'REVOKED'
        )
      ),
    constraint ck_authorization_seed_reason_code
      check (
        reason_code is null
        or reason_code in (
          'AUTH_NO_SESSION',
          'AUTH_USER_INACTIVE',
          'AUTH_APP_ACCESS_DENIED',
          'AUTH_ADMIN_PERMISSION_DENIED',
          'AUTH_OPERATIONAL_PERMISSION_DENIED',
          'AUTH_SITE_ASSIGNMENT_REQUIRED',
          'AUTH_ACTIVE_SITE_REQUIRED',
          'AUTH_AREA_ASSIGNMENT_REQUIRED',
          'AUTH_ACTIVE_AREA_REQUIRED',
          'AUTH_PUBLISHED_SHIFT_REQUIRED',
          'AUTH_OUTSIDE_SHIFT_WINDOW',
          'AUTH_CHECKIN_REQUIRED',
          'AUTH_OPERATIONAL_ROLE_REQUIRED',
          'AUTH_OPERATIONAL_ROLE_INVALID_FOR_SITE',
          'AUTH_OPERATIONAL_ROLE_INVALID_FOR_AREA',
          'AUTH_SHARED_DEVICE_NOT_AUTHORIZED',
          'AUTH_ACTION_NOT_ALLOWED_IN_SIMULATION',
          'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT',
          'AUTH_PERMISSION_NOT_REGISTERED',
          'AUTH_AUTHORIZATION_EVALUATION_UNAVAILABLE'
        )
      ),
    constraint ck_authorization_seed_deny_reason
      check (
        effect <> 'DENY'
        or reason_code is not null
      )
  );

create index if not exists
  ix_authorization_seed_lookup
on app_private.authorization_dataset_seed_records (
  subject_ref,
  permission_key,
  lane,
  effect,
  status
);

alter table
  app_private.authorization_contract_releases
enable row level security;

alter table
  app_private.authorization_permission_contracts
enable row level security;

alter table
  app_private.authorization_resource_resolver_registry
enable row level security;

alter table
  app_private.authorization_dataset_source_registry
enable row level security;

alter table
  app_private.authorization_base_role_grants
enable row level security;

alter table
  app_private.authorization_operational_role_grants
enable row level security;

alter table
  app_private.authorization_dataset_seed_records
enable row level security;

revoke all
on table
  app_private.authorization_contract_releases,
  app_private.authorization_permission_contracts,
  app_private.authorization_resource_resolver_registry,
  app_private.authorization_dataset_source_registry,
  app_private.authorization_base_role_grants,
  app_private.authorization_operational_role_grants,
  app_private.authorization_dataset_seed_records
