insert into
  app_private.authorization_resource_resolver_registry (
    resource_contract_id,
    resolver_key,
    resolver_version,
    resource_type,
    allowed_request_modes,
    owner_domain,
    source_contract_version,
    source_contract_fingerprint,
    resolver_shape_fingerprint,
    status
  )
select
  value ->> 'resource_contract_id',
  value ->> 'resolver_key',
  value ->> 'resolver_version',
  value ->> 'resource_type',
  array(
    select pg_catalog.jsonb_array_elements_text(
      value -> 'allowed_request_modes'
    )
  ),
  value ->> 'owner_domain',
  value ->> 'source_contract_version',
  value ->> 'source_contract_fingerprint',
  value ->> 'resolver_shape_fingerprint',
  value ->> 'status'
from payload
on conflict (
  resource_contract_id,
  resolver_version
)
do nothing;

