create or replace function
  app_private.canonicalize_authorization_payload(
    p_payload jsonb
  )
returns text
language plpgsql
immutable
strict
set search_path = pg_catalog, app_private
as $auth_db_034_canonicalize$
declare
  v_result text;
begin
  case pg_catalog.jsonb_typeof(p_payload)
    when 'object' then
      select
        '{' ||
        coalesce(
          pg_catalog.string_agg(
            pg_catalog.to_jsonb(key)::text ||
            ':' ||
            app_private.canonicalize_authorization_payload(value),
            ','
            order by key
          ),
          ''
        ) ||
        '}'
      into v_result
      from pg_catalog.jsonb_each(p_payload);

      return v_result;

    when 'array' then
      select
        '[' ||
        coalesce(
          pg_catalog.string_agg(
            app_private.canonicalize_authorization_payload(value),
            ','
            order by ordinality
          ),
          ''
        ) ||
        ']'
      into v_result
      from pg_catalog.jsonb_array_elements(p_payload)
        with ordinality as items(value, ordinality);

      return v_result;

    else
      return p_payload::text;
  end case;
end
$auth_db_034_canonicalize$;

create or replace function
  app_private.validate_authorization_evaluation_request(
    p_envelope jsonb
  )
returns jsonb
language plpgsql
immutable
strict
set search_path = pg_catalog, app_private
as $auth_db_034_validate_request$
declare
  v_request jsonb;
  v_resource jsonb;
  v_mode text;
  v_fields jsonb;
  v_root_count integer;
  v_request_count integer;
begin
  if pg_catalog.jsonb_typeof(p_envelope) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_REQUEST_ENVELOPE_INVALID';
  end if;

  select pg_catalog.count(*)
  into v_root_count
  from pg_catalog.jsonb_object_keys(p_envelope);

  if v_root_count <> 7
     or p_envelope ->> 'contract_family'
        <> 'vento.authorization.request-contracts'
     or p_envelope ->> 'contract_family_version'
        <> '1.0.0'
     or p_envelope ->> 'contract_name'
        <> 'AuthorizationEvaluationRequest'
     or p_envelope ->> 'contract_version'
        <> '1.0.0'
     or p_envelope ->> 'schema_version'
        <> '1.0.0'
     or not (p_envelope ? 'correlation_id')
     or pg_catalog.jsonb_typeof(
          p_envelope -> 'request'
        ) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_REQUEST_ENVELOPE_INCOMPATIBLE';
  end if;

  if (
    p_envelope -> 'correlation_id'
  ) <> 'null'::jsonb
  and pg_catalog.jsonb_typeof(
        p_envelope -> 'correlation_id'
      ) <> 'string' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_CORRELATION_ID_INVALID';
  end if;

  v_request :=
    p_envelope -> 'request';

  select pg_catalog.count(*)
  into v_request_count
  from pg_catalog.jsonb_object_keys(v_request);

  if v_request_count <> 6
     or nullif(
          v_request ->> 'app_code',
          ''
        ) is null
     or nullif(
          v_request ->> 'permission_key',
          ''
        ) is null
     or v_request ->> 'operation_kind'
        not in (
          'READ',
          'CREATE',
          'UPDATE',
          'DELETE',
          'EXECUTE',
          'TRANSITION',
          'EXPORT',
          'APP_ACCESS'
        )
     or v_request ->> 'request_source'
        not in (
          'SERVER_ACTION',
          'RPC',
          'RLS',
          'API',
          'UI_GUARD',
          'JOB'
        )
     or pg_catalog.jsonb_typeof(
          v_request -> 'resource_request'
        ) <> 'object'
     or pg_catalog.jsonb_typeof(
          v_request -> 'requested_fields'
        ) <> 'array' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_REQUEST_SHAPE_INVALID';
  end if;

  if v_request ?| array[
       'context_id',
       'AccessContext',
       'principal_id',
       'actor_id',
       'employee_id',
       'base_role',
       'operational_role',
       'effective_site_id',
       'effective_area_id',
       'shift_id',
       'checkin_id',
       'device_id',
       'authorization_requirement',
       'grants',
       'allows',
       'denies',
       'decision_id',
       'outcome',
       'catalog_hash',
       'dataset_hashes',
       'expected_outcome',
       'allow',
       'can_operate',
       'bypass',
       'force_allow',
       'ignore_denies',
       'skip_resource_resolution',
       'skip_prerequisites'
     ] then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_REQUEST_EFFECTIVE_FACTS_FORBIDDEN';
  end if;

  v_resource :=
    v_request -> 'resource_request';

  v_mode :=
    v_resource ->> 'mode';

  if v_mode not in (
       'EXISTING_RESOURCE',
       'RESOURCE_DRAFT',
       'COLLECTION',
       'AGGREGATE',
       'BULK',
       'NON_RESOURCE'
     ) then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_RESOURCE_MODE_INVALID';
  end if;

  if v_resource ?| array[
       'actor_id',
       'principal_id',
       'employee_id',
       'base_role',
       'operational_role',
       'allow',
       'bypass',
       'force_allow',
       'skip_resource_resolution'
     ] then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_RESOURCE_REQUEST_AUTHORITY_FORBIDDEN';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(
      v_request -> 'requested_fields'
    ) as item(value)
    where pg_catalog.jsonb_typeof(value) <> 'string'
       or nullif(value #>> '{}', '') is null
  ) then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_REQUESTED_FIELDS_INVALID';
  end if;

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(field_name)
        order by field_name
      ),
      '[]'::jsonb
    )
  into v_fields
  from (
    select distinct value as field_name
    from pg_catalog.jsonb_array_elements_text(
      v_request -> 'requested_fields'
    ) as field(value)
  ) normalized;

  return pg_catalog.jsonb_set(
    p_envelope,
    '{request,requested_fields}',
    v_fields,
    true
  );
end
$auth_db_034_validate_request$;

create or replace function
  app_private.resolve_permission_contract_snapshot(
    p_app_code text,
    p_permission_key text
  )
returns jsonb
language plpgsql
stable
set search_path = pg_catalog, app_private
as $auth_db_034_resolve_permission$
declare
  v_count integer;
  v_result jsonb;
begin
  select
    pg_catalog.count(*)
  into
    v_count
  from
    app_private.authorization_permission_contracts p
  join
    app_private.authorization_contract_releases r
      on r.catalog_id = p.catalog_id
     and r.catalog_version = p.catalog_version
  where r.status = 'ACTIVE'
    and p.status = 'ACTIVE'
    and p.app_code = p_app_code
    and p.permission_key = p_permission_key;

  if v_count = 0 then
    return null;
  end if;

  if v_count <> 1 then
    return null;
  end if;

  select
    p.contract_snapshot ||
    pg_catalog.jsonb_build_object(
      'contract_fingerprint',
      p.contract_fingerprint
    )
  into
    v_result
  from
    app_private.authorization_permission_contracts p
  join
    app_private.authorization_contract_releases r
      on r.catalog_id = p.catalog_id
     and r.catalog_version = p.catalog_version
  where r.status = 'ACTIVE'
    and p.status = 'ACTIVE'
    and p.app_code = p_app_code
    and p.permission_key = p_permission_key;

  return v_result;
end
$auth_db_034_resolve_permission$;

create or replace function
  app_private.resolve_authorization_resource(
    p_resource_contract_id text,
    p_resource_request jsonb,
    p_operation_kind text,
    p_requested_fields text[]
  )
returns jsonb
language plpgsql
stable
set search_path = pg_catalog, app_private
as $auth_db_034_resolve_resource$
declare
  v_registry record;
  v_mode text;
  v_fields text[];
  v_fingerprint text;
  v_state text;
  v_safe_reference jsonb;
begin
  if p_resource_request is null
     or pg_catalog.jsonb_typeof(p_resource_request) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_RESOURCE_REQUEST_INVALID';
  end if;

  v_mode :=
    p_resource_request ->> 'mode';

  if v_mode not in (
       'EXISTING_RESOURCE',
       'RESOURCE_DRAFT',
       'COLLECTION',
       'AGGREGATE',
       'BULK',
       'NON_RESOURCE'
     ) then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_RESOURCE_MODE_INVALID';
  end if;

  select
    coalesce(
      pg_catalog.array_agg(
        distinct field_name
        order by field_name
      ),
      '{}'::text[]
    )
  into v_fields
  from pg_catalog.unnest(
    coalesce(
      p_requested_fields,
      '{}'::text[]
    )
  ) as field(field_name)
  where nullif(field_name, '') is not null;

  select
    *
  into v_registry
  from
    app_private.authorization_resource_resolver_registry
  where resource_contract_id =
        p_resource_contract_id
    and status = 'ACTIVE';

  v_fingerprint :=
    'sha256:' ||
    pg_catalog.encode(
      extensions.digest(
        app_private.canonicalize_authorization_payload(
          pg_catalog.jsonb_build_object(
            'resource_contract_id',
            p_resource_contract_id,
            'resource_request',
            p_resource_request,
            'operation_kind',
            p_operation_kind,
            'requested_fields',
            pg_catalog.to_jsonb(v_fields)
          )
        ),
        'sha256'
      ),
      'hex'
    );

  if not found then
    return pg_catalog.jsonb_build_object(
      'resource_contract_id',
      p_resource_contract_id,
      'resolver_key',
      null,
      'resource_type',
      null,
      'request_mode',
      v_mode,
      'resolution_state',
      'UNRESOLVED',
      'resource_fingerprint',
      v_fingerprint,
      'safe_resource_reference',
      null,
      'requested_fields',
      pg_catalog.to_jsonb(v_fields)
    );
  end if;

  if not (
    v_mode = any(
      v_registry.allowed_request_modes
    )
  ) then
    v_state :=
      'CONFLICT';

    v_safe_reference :=
      null;

  elsif
    v_registry.resolver_key =
      'APP_SURFACE_NON_RESOURCE'
    and v_registry.resource_type =
      'APP_SURFACE'
    and v_mode =
      'NON_RESOURCE' then

    v_state :=
      'NOT_APPLICABLE';

    v_safe_reference :=
      pg_catalog.jsonb_build_object(
        'resource_type',
        'APP_SURFACE'
      );

  elsif v_mode = 'NON_RESOURCE' then
    v_state :=
      'CONFLICT';

    v_safe_reference :=
      null;

  else
    -- AUTH-DB-034 must not invent owner-relation mappings.
    -- Until a static certified domain resolver exists this is
    -- an explicit fail-closed state with zero territorial fallback.
    v_state :=
      'UNRESOLVED';

    v_safe_reference :=
      null;
  end if;

  return pg_catalog.jsonb_build_object(
    'resource_contract_id',
    p_resource_contract_id,
    'resolver_key',
    v_registry.resolver_key,
    'resource_type',
    v_registry.resource_type,
    'request_mode',
    v_mode,
    'resolution_state',
    v_state,
    'resource_fingerprint',
    v_fingerprint,
    'safe_resource_reference',
    v_safe_reference,
    'requested_fields',
    pg_catalog.to_jsonb(v_fields)
  );
end
$auth_db_034_resolve_resource$;

create or replace function
  app_private.load_authorization_datasets(
    p_permission_contract jsonb,
    p_access_context jsonb,
    p_resource jsonb
  )
returns jsonb
language plpgsql
stable
set search_path = pg_catalog, app_private
as $auth_db_034_load_datasets$
declare
  v_permission_key text;
  v_base_role text;
  v_operational_role text;
  v_actor_id text;

  v_base_grants jsonb;
  v_operational_grants jsonb;
  v_individual_overrides jsonb;
  v_actor_wide_denies jsonb;
  v_base_lane_denies jsonb;
  v_operational_lane_denies jsonb;
  v_dataset_evidence jsonb;
begin
  v_permission_key :=
    p_permission_contract ->> 'permission_key';

  v_base_role :=
    p_access_context #>>
      '{base_role,role_code}';

  v_operational_role :=
    p_access_context #>>
      '{operational_role,role_code}';

  v_actor_id :=
    p_access_context #>>
      '{actor_effective,actor_id}';

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          grant_id,
          'lane',
          'BASE',
          'source',
          'BASE_ROLE_DATASET',
          'role_code',
          role_code,
          'scope_expression',
          scope_expression,
          'condition_expression',
          condition_expression,
          'effect',
          effect
        )
        order by grant_id
      ),
      '[]'::jsonb
    )
  into v_base_grants
  from
    app_private.authorization_base_role_grants
  where dataset_version = '1.1.0'
    and role_code = v_base_role
    and permission_key = v_permission_key
    and effect = 'ALLOW';

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          grant_id,
          'lane',
          'OPERATIONAL',
          'source',
          'OPERATIONAL_ROLE_DATASET',
          'role_code',
          operational_role_code,
          'scope_expression',
          scope_expression,
          'condition_expression',
          condition_expression,
          'effect',
          effect
        )
        order by grant_id
      ),
      '[]'::jsonb
    )
  into v_operational_grants
  from
    app_private.authorization_operational_role_grants
  where dataset_version = '1.0.0'
    and operational_role_code =
        v_operational_role
    and permission_key =
        v_permission_key
    and effect = 'ALLOW';

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          record_id,
          'lane',
          lane,
          'source',
          'INDIVIDUAL_OVERRIDE',
          'scope_code',
          scope_code,
          'effect',
          effect
        )
        order by record_id
      ),
      '[]'::jsonb
    )
  into v_individual_overrides
  from
    app_private.authorization_dataset_seed_records
  where status = 'ACTIVE'
    and subject_type = 'ACTOR'
    and subject_ref = v_actor_id
    and permission_key = v_permission_key
    and effect = 'ALLOW'
    and lane in (
      'BASE',
      'OPERATIONAL'
    )
    and (
      valid_from is null
      or valid_from <=
         pg_catalog.statement_timestamp()
    )
    and (
      valid_until is null
      or valid_until >
         pg_catalog.statement_timestamp()
    );

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          record_id,
          'lane',
          lane,
          'source',
          'ACTOR_WIDE_DENY',
          'scope_code',
          scope_code,
          'effect',
          effect,
          'reason_code',
          reason_code
        )
        order by record_id
      ),
      '[]'::jsonb
    )
  into v_actor_wide_denies
  from
    app_private.authorization_dataset_seed_records
  where status = 'ACTIVE'
    and subject_type = 'ACTOR'
    and subject_ref = v_actor_id
    and permission_key is null
    and effect = 'DENY'
    and lane = 'ALL'
    and (
      valid_from is null
      or valid_from <=
         pg_catalog.statement_timestamp()
    )
    and (
      valid_until is null
      or valid_until >
         pg_catalog.statement_timestamp()
    );

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          record_id,
          'lane',
          lane,
          'source',
          'LANE_DENY',
          'scope_code',
          scope_code,
          'effect',
          effect,
          'reason_code',
          reason_code
        )
        order by record_id
      ),
      '[]'::jsonb
    )
  into v_base_lane_denies
  from
    app_private.authorization_dataset_seed_records
  where status = 'ACTIVE'
    and subject_type = 'ACTOR'
    and subject_ref = v_actor_id
    and permission_key = v_permission_key
    and effect = 'DENY'
    and lane = 'BASE'
    and (
      valid_from is null
      or valid_from <=
         pg_catalog.statement_timestamp()
    )
    and (
      valid_until is null
      or valid_until >
         pg_catalog.statement_timestamp()
    );

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id',
          record_id,
          'lane',
          lane,
          'source',
          'LANE_DENY',
          'scope_code',
          scope_code,
          'effect',
          effect,
          'reason_code',
          reason_code
        )
        order by record_id
      ),
      '[]'::jsonb
    )
  into v_operational_lane_denies
  from
    app_private.authorization_dataset_seed_records
  where status = 'ACTIVE'
    and subject_type = 'ACTOR'
    and subject_ref = v_actor_id
    and permission_key = v_permission_key
    and effect = 'DENY'
    and lane = 'OPERATIONAL'
    and (
      valid_from is null
      or valid_from <=
         pg_catalog.statement_timestamp()
    )
    and (
      valid_until is null
      or valid_until >
         pg_catalog.statement_timestamp()
    );

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'dataset_key',
          dataset_key,
          'dataset_version',
          dataset_version,
          'dataset_fingerprint',
          source_shape_fingerprint
        )
        order by dataset_key
      ),
      '[]'::jsonb
    )
  into v_dataset_evidence
  from
    app_private.authorization_dataset_source_registry
  where status = 'ACTIVE';

  return pg_catalog.jsonb_build_object(
    'base_grants',
    v_base_grants,
    'operational_grants',
    v_operational_grants,
    'individual_overrides',
    v_individual_overrides,
    'actor_wide_denies',
    v_actor_wide_denies,
    'base_lane_denies',
    v_base_lane_denies,
    'operational_lane_denies',
    v_operational_lane_denies,
    'dataset_evidence',
    v_dataset_evidence
  );
end
$auth_db_034_load_datasets$;

create or replace function
  app_private.evaluate_authorization_core(
    p_validated_request jsonb,
    p_access_context jsonb,
    p_decision_id uuid,
    p_decided_at timestamptz,
    p_dependency_stack text[],
    p_dependency_depth integer
  )
returns jsonb
language plpgsql
stable
set search_path = pg_catalog, app_private
as $auth_db_034_core$
declare
  v_request jsonb;
  v_app_code text;
  v_permission_key text;
  v_operation_kind text;
  v_request_source text;

  v_permission jsonb;
  v_resource jsonb;
  v_datasets jsonb;

  v_requirement text;
  v_resource_type text;
  v_resource_contract_id text;
  v_requested_fields text[];

  v_structural_codes text[] :=
    '{}'::text[];

  v_base_reasons text[] :=
    '{}'::text[];

  v_operational_reasons text[] :=
    '{}'::text[];

  v_device_reasons text[] :=
    '{}'::text[];

  v_blocked_codes text[] :=
    '{}'::text[];

  v_base_applicable boolean := false;
  v_operational_applicable boolean := false;

  v_base_allows jsonb :=
    '[]'::jsonb;

  v_operational_allows jsonb :=
    '[]'::jsonb;

  v_base_denies jsonb :=
    '[]'::jsonb;

  v_operational_denies jsonb :=
    '[]'::jsonb;

  v_actor_wide_denies jsonb :=
    '[]'::jsonb;

  v_matched_allows jsonb :=
    '[]'::jsonb;

  v_matched_denies jsonb :=
    '[]'::jsonb;

  v_lane_denies jsonb :=
    '[]'::jsonb;

  v_structural_denies jsonb :=
    '[]'::jsonb;

  v_prerequisite_decisions jsonb :=
    '[]'::jsonb;

  v_base_decision jsonb :=
    pg_catalog.jsonb_build_object(
      'evaluated',
      false,
      'outcome',
      'NOT_APPLICABLE',
      'reason_codes',
      '[]'::jsonb,
      'matched_allows',
      '[]'::jsonb,
      'matched_denies',
      '[]'::jsonb
    );

  v_operational_decision jsonb :=
    pg_catalog.jsonb_build_object(
      'evaluated',
      false,
      'outcome',
      'NOT_APPLICABLE',
      'reason_codes',
      '[]'::jsonb,
      'matched_allows',
      '[]'::jsonb,
      'matched_denies',
      '[]'::jsonb
    );

  v_device_decision jsonb :=
    pg_catalog.jsonb_build_object(
      'outcome',
      'ALLOW',
      'status',
      'NOT_APPLICABLE',
      'reason_codes',
      '[]'::jsonb
    );

  v_sensitivity_decision jsonb :=
    pg_catalog.jsonb_build_object(
      'outcome',
      'ALLOW',
      'is_sensitive',
      false
    );

  v_field_policy_decision jsonb :=
    pg_catalog.jsonb_build_object(
      'outcome',
      'ALLOW',
      'visible_fields',
      '[]'::jsonb
    );

  v_required_lanes text[] :=
    '{}'::text[];

  v_base_outcome text :=
    'NOT_APPLICABLE';

  v_operational_outcome text :=
    'NOT_APPLICABLE';

  v_combination_outcome text :=
    'DENY';

  v_final_decision text :=
    'DENY';

  v_context_fingerprint text;
  v_request_fingerprint text;

  v_device_policy text;
  v_area_requirement text;
  v_requires_checkin boolean := false;

  v_dep text;
  v_dep_app text;
  v_dep_request jsonb;
  v_dep_decision jsonb;

  v_cycle_or_depth boolean := false;
begin
  if pg_catalog.jsonb_typeof(
       p_validated_request
     ) <> 'object'
     or pg_catalog.jsonb_typeof(
          p_validated_request -> 'request'
        ) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_CORE_REQUEST_INVALID';
  end if;

  v_request :=
    p_validated_request -> 'request';

  v_app_code :=
    v_request ->> 'app_code';

  v_permission_key :=
    v_request ->> 'permission_key';

  v_operation_kind :=
    v_request ->> 'operation_kind';

  v_request_source :=
    v_request ->> 'request_source';

  select
    coalesce(
      pg_catalog.array_agg(
        distinct field_name
        order by field_name
      ),
      '{}'::text[]
    )
  into v_requested_fields
  from pg_catalog.jsonb_array_elements_text(
    v_request -> 'requested_fields'
  ) as field(field_name);

  if p_dependency_depth > 32 then
    v_structural_codes :=
      pg_catalog.array_append(
        v_structural_codes,
        'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
      );

    v_cycle_or_depth := true;
  end if;

  if v_permission_key = any(
       coalesce(
         p_dependency_stack,
         '{}'::text[]
       )
     ) then
    v_structural_codes :=
      pg_catalog.array_append(
        v_structural_codes,
        'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
      );

    v_cycle_or_depth := true;
  end if;

  v_permission :=
    app_private.resolve_permission_contract_snapshot(
      v_app_code,
      v_permission_key
    );

  if v_permission is null then
    v_structural_codes :=
      pg_catalog.array_append(
        v_structural_codes,
        'AUTH_PERMISSION_NOT_REGISTERED'
      );

    v_resource :=
      pg_catalog.jsonb_build_object(
        'resource_contract_id',
        null,
        'resolver_key',
        null,
        'resource_type',
        null,
        'request_mode',
        v_request #>>
          '{resource_request,mode}',
        'resolution_state',
        'UNRESOLVED',
        'resource_fingerprint',
        null,
        'safe_resource_reference',
        null,
        'requested_fields',
        pg_catalog.to_jsonb(
          v_requested_fields
        )
      );

    v_datasets :=
      pg_catalog.jsonb_build_object(
        'base_grants',
        '[]'::jsonb,
        'operational_grants',
        '[]'::jsonb,
        'individual_overrides',
        '[]'::jsonb,
        'actor_wide_denies',
        '[]'::jsonb,
        'base_lane_denies',
        '[]'::jsonb,
        'operational_lane_denies',
        '[]'::jsonb,
        'dataset_evidence',
        '[]'::jsonb
      );

  else
    v_requirement :=
      v_permission ->>
        'authorization_requirement';

    v_resource_type :=
      v_permission ->>
        'resource_type';

    v_resource_contract_id :=
      v_permission ->>
        'resource_contract_id';

    v_base_applicable :=
      v_requirement in (
        'BASE_ONLY',
        'BASE_OR_OPERATIONAL',
        'BASE_AND_OPERATIONAL'
      );

    v_operational_applicable :=
      v_requirement in (
        'OPERATIONAL_ONLY',
        'BASE_OR_OPERATIONAL',
        'BASE_AND_OPERATIONAL'
      );

    if v_base_applicable then
      v_required_lanes :=
        pg_catalog.array_append(
          v_required_lanes,
          'BASE'
        );
    end if;

    if v_operational_applicable then
      v_required_lanes :=
        pg_catalog.array_append(
          v_required_lanes,
          'OPERATIONAL'
        );
    end if;

    v_resource :=
      app_private.resolve_authorization_resource(
        v_resource_contract_id,
        v_request -> 'resource_request',
        v_operation_kind,
        v_requested_fields
      );

    v_datasets :=
      app_private.load_authorization_datasets(
        v_permission,
        p_access_context,
        v_resource
      );

    if p_access_context ->> 'contract_family'
         <> 'vento.authorization.response-contracts'
       or p_access_context ->> 'contract_name'
         <> 'AccessContext'
       or p_access_context ->> 'contract_version'
         <> '1.0.0'
       or p_access_context ->> 'schema_version'
         <> '1.0.0'
       or nullif(
            p_access_context ->> 'context_id',
            ''
          ) is null then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_AUTHORIZATION_EVALUATION_UNAVAILABLE'
        );
    end if;

    if not coalesce(
         (
           p_access_context #>>
             '{principal,authenticated}'
         )::boolean,
         false
       )
       or coalesce(
            p_access_context #>>
              '{principal,principal_status}',
            ''
          ) <> 'VALID' then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_NO_SESSION'
        );
    end if;

    if not coalesce(
         (
           p_access_context #>>
             '{actor_effective,resolved}'
         )::boolean,
         false
       )
       or nullif(
            p_access_context #>>
              '{actor_effective,actor_id}',
            ''
          ) is null then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_AUTHORIZATION_EVALUATION_UNAVAILABLE'
        );
    end if;

    if p_access_context -> 'employee'
         is null
       or p_access_context -> 'employee'
         = 'null'::jsonb
       or not coalesce(
            (
              p_access_context #>>
                '{employee,is_active}'
            )::boolean,
            false
          ) then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_USER_INACTIVE'
        );
    end if;

    if coalesce(
         pg_catalog.jsonb_array_length(
           p_access_context ->
             'structural_issues'
         ),
         0
       ) > 0 then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_AUTHORIZATION_EVALUATION_UNAVAILABLE'
        );
    end if;

    if coalesce(
         (
           v_permission ->>
             'is_read_only'
         )::boolean,
         false
       )
       and v_operation_kind not in (
         'READ',
         'APP_ACCESS'
       ) then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
        );
    end if;

    if v_resource_type =
         'APP_SURFACE'
       and v_operation_kind <>
         'APP_ACCESS' then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
        );
    end if;

    if v_resource_type <>
         'APP_SURFACE'
       and v_operation_kind =
         'APP_ACCESS' then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
        );
    end if;

    if v_resource ->>
         'resolution_state'
       in (
         'UNRESOLVED',
         'CONFLICT',
         'ISOLATED'
       ) then
      v_structural_codes :=
        pg_catalog.array_append(
          v_structural_codes,
          'AUTH_AUTHORIZATION_EVALUATION_UNAVAILABLE'
        );
    end if;

    v_actor_wide_denies :=
      coalesce(
        v_datasets ->
          'actor_wide_denies',
        '[]'::jsonb
      );

    /*
     * BASE lane.
     */
    if v_base_applicable then
      v_base_allows :=
        coalesce(
          v_datasets ->
            'base_grants',
          '[]'::jsonb
        );

      select
        v_base_allows ||
        coalesce(
          pg_catalog.jsonb_agg(
            item.value
            order by item.value ->> 'id'
          ),
          '[]'::jsonb
        )
      into v_base_allows
      from pg_catalog.jsonb_array_elements(
        coalesce(
          v_datasets ->
            'individual_overrides',
          '[]'::jsonb
        )
      ) as item(value)
      where item.value ->>
            'lane' = 'BASE';

      v_base_denies :=
        coalesce(
          v_datasets ->
            'base_lane_denies',
          '[]'::jsonb
        );

      if coalesce(
           p_access_context #>>
             '{lane_readiness,base,status}',
           ''
         ) <> 'READY'
         or coalesce(
              p_access_context #>>
                '{base_role,role_status}',
              ''
            ) <> 'ACTIVE'
         or nullif(
              p_access_context #>>
                '{base_role,role_code}',
              ''
            ) is null then

        v_base_reasons :=
          pg_catalog.array_append(
            v_base_reasons,
            'AUTH_ADMIN_PERMISSION_DENIED'
          );

        v_base_outcome :=
          'DENY';

      elsif pg_catalog.jsonb_array_length(
              v_base_denies
            ) > 0 then

        select
          coalesce(
            pg_catalog.array_agg(
              distinct item.value ->>
                'reason_code'
              order by item.value ->>
                'reason_code'
            ),
            '{}'::text[]
          )
        into v_base_reasons
        from pg_catalog.jsonb_array_elements(
          v_base_denies
        ) as item(value);

        v_base_outcome :=
          'DENY';

      elsif pg_catalog.jsonb_array_length(
              v_base_allows
            ) > 0 then

        v_base_outcome :=
          'ALLOW';

      else
        v_base_reasons :=
          pg_catalog.array_append(
            v_base_reasons,
            'AUTH_ADMIN_PERMISSION_DENIED'
          );

        v_base_outcome :=
          'DENY';
      end if;

      v_base_decision :=
        pg_catalog.jsonb_build_object(
          'evaluated',
          true,
          'outcome',
          v_base_outcome,
          'reason_codes',
          pg_catalog.to_jsonb(
            v_base_reasons
          ),
          'matched_allows',
          v_base_allows,
          'matched_denies',
          v_base_denies
        );
    end if;

    /*
     * OPERATIONAL lane.
     */
    if v_operational_applicable then
      v_operational_allows :=
        coalesce(
          v_datasets ->
            'operational_grants',
          '[]'::jsonb
        );

      select
        v_operational_allows ||
        coalesce(
          pg_catalog.jsonb_agg(
            item.value
            order by item.value ->> 'id'
          ),
          '[]'::jsonb
        )
      into v_operational_allows
      from pg_catalog.jsonb_array_elements(
        coalesce(
          v_datasets ->
            'individual_overrides',
          '[]'::jsonb
        )
      ) as item(value)
      where item.value ->>
            'lane' = 'OPERATIONAL';

      v_operational_denies :=
        coalesce(
          v_datasets ->
            'operational_lane_denies',
          '[]'::jsonb
        );

      v_area_requirement :=
        v_permission ->>
          'area_requirement';

      v_requires_checkin :=
        coalesce(
          (
            v_permission #>>
              '{operational_lane,requires_checkin}'
          )::boolean,
          false
        );

      if coalesce(
           p_access_context #>>
             '{lane_readiness,operational,status}',
           ''
         ) <> 'READY' then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_OPERATIONAL_PERMISSION_DENIED'
          );

      elsif p_access_context ->
              'active_shift'
            is null
         or p_access_context ->
              'active_shift'
            = 'null'::jsonb
         or not coalesce(
              (
                p_access_context #>>
                  '{active_shift,published}'
              )::boolean,
              false
            ) then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_PUBLISHED_SHIFT_REQUIRED'
          );

      elsif not coalesce(
              (
                p_access_context #>>
                  '{active_shift,currently_valid}'
              )::boolean,
              false
            ) then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_OUTSIDE_SHIFT_WINDOW'
          );

      elsif nullif(
              p_access_context #>>
                '{operational_role,role_code}',
              ''
            ) is null then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_OPERATIONAL_ROLE_REQUIRED'
          );

      elsif not coalesce(
              (
                p_access_context #>>
                  '{operational_role,valid_for_site}'
              )::boolean,
              false
            ) then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_OPERATIONAL_ROLE_INVALID_FOR_SITE'
          );

      elsif v_area_requirement =
              'REQUIRED'
        and (
          p_access_context ->
            'operational_area'
          is null
          or p_access_context ->
            'operational_area'
          = 'null'::jsonb
          or not coalesce(
               (
                 p_access_context #>>
                   '{operational_area,area_active}'
               )::boolean,
               false
             )
          or not coalesce(
               (
                 p_access_context #>>
                   '{operational_area,compatible_with_role}'
               )::boolean,
               false
             )
        ) then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_ACTIVE_AREA_REQUIRED'
          );

      elsif v_requires_checkin
        and (
          p_access_context ->
            'active_checkin_session'
          is null
          or p_access_context ->
            'active_checkin_session'
          = 'null'::jsonb
          or coalesce(
               p_access_context #>>
                 '{active_checkin_session,status}',
               ''
             ) <> 'ACTIVE'
        ) then

        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_CHECKIN_REQUIRED'
          );
      end if;

      if pg_catalog.cardinality(
           v_operational_reasons
         ) > 0 then

        v_operational_outcome :=
          'DENY';

      elsif pg_catalog.jsonb_array_length(
              v_operational_denies
            ) > 0 then

        select
          coalesce(
            pg_catalog.array_agg(
              distinct item.value ->>
                'reason_code'
              order by item.value ->>
                'reason_code'
            ),
            '{}'::text[]
          )
        into v_operational_reasons
        from pg_catalog.jsonb_array_elements(
          v_operational_denies
        ) as item(value);

        v_operational_outcome :=
          'DENY';

      elsif pg_catalog.jsonb_array_length(
              v_operational_allows
            ) > 0 then

        v_operational_outcome :=
          'ALLOW';

      else
        v_operational_reasons :=
          pg_catalog.array_append(
            v_operational_reasons,
            'AUTH_OPERATIONAL_PERMISSION_DENIED'
          );

        v_operational_outcome :=
          'DENY';
      end if;

      v_operational_decision :=
        pg_catalog.jsonb_build_object(
          'evaluated',
          true,
          'outcome',
          v_operational_outcome,
          'reason_codes',
          pg_catalog.to_jsonb(
            v_operational_reasons
          ),
          'matched_allows',
          v_operational_allows,
          'matched_denies',
          v_operational_denies
        );
    end if;

    /*
     * Dependency graph.
     */
    if not v_cycle_or_depth then
      for v_dep in
        select
          value
        from pg_catalog.jsonb_array_elements_text(
          coalesce(
            v_permission ->
              'dependency_permissions',
            '[]'::jsonb
          )
        ) as dependency(value)
        order by value
      loop
        select
          p.app_code
        into v_dep_app
        from
          app_private.authorization_permission_contracts p
        join
          app_private.authorization_contract_releases r
            on r.catalog_id =
               p.catalog_id
           and r.catalog_version =
               p.catalog_version
        where r.status = 'ACTIVE'
          and p.status = 'ACTIVE'
          and p.permission_key =
              v_dep
        limit 1;

        if v_dep_app is null then
          v_structural_codes :=
            pg_catalog.array_append(
              v_structural_codes,
              'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
            );

          v_prerequisite_decisions :=
            v_prerequisite_decisions ||
            pg_catalog.jsonb_build_array(
              pg_catalog.jsonb_build_object(
                'permission_key',
                v_dep,
                'final_decision',
                'DENY'
              )
            );

          continue;
        end if;

        v_dep_request :=
          pg_catalog.jsonb_set(
            p_validated_request,
            '{request,app_code}',
            pg_catalog.to_jsonb(
              v_dep_app
            ),
            true
          );

        v_dep_request :=
          pg_catalog.jsonb_set(
            v_dep_request,
            '{request,permission_key}',
            pg_catalog.to_jsonb(
              v_dep
            ),
            true
          );

        v_dep_decision :=
          app_private.evaluate_authorization_core(
            v_dep_request,
            p_access_context,
            p_decision_id,
            p_decided_at,
            pg_catalog.array_append(
              coalesce(
                p_dependency_stack,
                '{}'::text[]
              ),
              v_permission_key
            ),
            p_dependency_depth + 1
          );

        v_prerequisite_decisions :=
          v_prerequisite_decisions ||
          pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object(
              'permission_key',
              v_dep,
              'final_decision',
              v_dep_decision ->>
                'final_decision'
            )
          );

        if v_dep_decision ->>
             'final_decision'
           <> 'ALLOW' then
          v_structural_codes :=
            pg_catalog.array_append(
              v_structural_codes,
              'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
            );
        end if;
      end loop;
    end if;

    /*
     * Device restriction.
     */
    v_device_policy :=
      v_permission ->>
        'device_policy';

    if p_access_context ->
         'device_context'
       is not null
       and p_access_context ->
         'device_context'
       <> 'null'::jsonb then

      if v_device_policy =
           'NOT_ALLOWED' then

        v_device_reasons :=
          pg_catalog.array_append(
            v_device_reasons,
            'AUTH_SHARED_DEVICE_NOT_AUTHORIZED'
          );

      elsif v_device_policy =
              'STRONG_REAUTH_REQUIRED' then

        -- AccessContextV1 currently carries no certified strong
        -- reauthentication proof. Fail closed.
        v_device_reasons :=
          pg_catalog.array_append(
            v_device_reasons,
            'AUTH_SHARED_DEVICE_NOT_AUTHORIZED'
          );

      elsif v_device_policy =
              'STANDARD_ACTOR_SESSION'
        and (
          coalesce(
            p_access_context #>>
              '{device_context,device_status}',
            ''
          ) <> 'ACTIVE'
          or not coalesce(
               (
                 p_access_context #>>
                   '{device_context,authenticated_as_device}'
               )::boolean,
               false
             )
          or nullif(
               p_access_context #>>
                 '{device_context,actor_session_id}',
               ''
             ) is null
          or not (
            p_access_context #>
              '{device_context,allowed_application_codes}'
            ? v_app_code
          )
        ) then

        v_device_reasons :=
          pg_catalog.array_append(
            v_device_reasons,
            'AUTH_SHARED_DEVICE_NOT_AUTHORIZED'
          );
      end if;

      if pg_catalog.cardinality(
           v_device_reasons
         ) > 0 then
        v_device_decision :=
          pg_catalog.jsonb_build_object(
            'outcome',
            'DENY',
            'status',
            'EVALUATED',
            'reason_codes',
            pg_catalog.to_jsonb(
              v_device_reasons
            )
          );
      else
        v_device_decision :=
          pg_catalog.jsonb_build_object(
            'outcome',
            'ALLOW',
            'status',
            'EVALUATED',
            'reason_codes',
            '[]'::jsonb
          );
      end if;
    end if;

    v_sensitivity_decision :=
      pg_catalog.jsonb_build_object(
        'outcome',
        'ALLOW',
        'is_sensitive',
        coalesce(
          (
            v_permission #>>
              '{sensitivity,is_sensitive}'
          )::boolean,
          false
        )
      );

    v_field_policy_decision :=
      pg_catalog.jsonb_build_object(
        'outcome',
        'ALLOW',
        'visible_fields',
        pg_catalog.to_jsonb(
          v_requested_fields
        )
      );

    case v_requirement
      when 'BASE_ONLY' then
        if v_base_outcome =
             'ALLOW' then
          v_combination_outcome :=
            'ALLOW';
        end if;

      when 'OPERATIONAL_ONLY' then
        if v_operational_outcome =
             'ALLOW' then
          v_combination_outcome :=
            'ALLOW';
        end if;

      when 'BASE_OR_OPERATIONAL' then
        if v_base_outcome =
             'ALLOW'
           or v_operational_outcome =
             'ALLOW' then
          v_combination_outcome :=
            'ALLOW';
        end if;

      when 'BASE_AND_OPERATIONAL' then
        if v_base_outcome =
             'ALLOW'
           and v_operational_outcome =
             'ALLOW' then
          v_combination_outcome :=
            'ALLOW';
        end if;

      else
        v_structural_codes :=
          pg_catalog.array_append(
            v_structural_codes,
            'AUTH_ADMINISTRATIVE_CONFIGURATION_INCONSISTENT'
          );
    end case;
  end if;

  /*
   * Consolidate evidence.
   */
  v_matched_allows :=
    coalesce(
      v_base_allows,
      '[]'::jsonb
    ) ||
    coalesce(
      v_operational_allows,
      '[]'::jsonb
    );

  v_lane_denies :=
    coalesce(
      v_base_denies,
      '[]'::jsonb
    ) ||
    coalesce(
      v_operational_denies,
      '[]'::jsonb
    );

  v_matched_denies :=
    coalesce(
      v_actor_wide_denies,
      '[]'::jsonb
    ) ||
    v_lane_denies;

  select
    coalesce(
      pg_catalog.jsonb_agg(
        item.value
        order by item.value ->> 'id'
      ),
      '[]'::jsonb
    )
  into v_matched_allows
  from pg_catalog.jsonb_array_elements(
    v_matched_allows
  ) as item(value);

  select
    coalesce(
      pg_catalog.jsonb_agg(
        item.value
        order by item.value ->> 'id'
      ),
      '[]'::jsonb
    )
  into v_matched_denies
  from pg_catalog.jsonb_array_elements(
    v_matched_denies
  ) as item(value);

  select
    coalesce(
      pg_catalog.array_agg(
        distinct code
        order by code
      ),
      '{}'::text[]
    )
  into v_structural_codes
  from pg_catalog.unnest(
    v_structural_codes
  ) as reason(code);

  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'reason_code',
          code,
          'source',
          'STRUCTURAL'
        )
        order by code
      ),
      '[]'::jsonb
    )
  into v_structural_denies
  from pg_catalog.unnest(
    v_structural_codes
  ) as reason(code);

  if pg_catalog.cardinality(
       v_structural_codes
     ) = 0
     and pg_catalog.jsonb_array_length(
           v_actor_wide_denies
         ) = 0
     and v_combination_outcome =
         'ALLOW'
     and v_device_decision ->>
         'outcome' = 'ALLOW'
     and v_field_policy_decision ->>
         'outcome' = 'ALLOW' then

    v_final_decision :=
      'ALLOW';

  else
    v_final_decision :=
      'DENY';
  end if;

  if v_final_decision =
       'DENY' then

    v_blocked_codes :=
      v_structural_codes;

    select
      v_blocked_codes ||
      coalesce(
        pg_catalog.array_agg(
          distinct item.value ->>
            'reason_code'
          order by item.value ->>
            'reason_code'
        ),
        '{}'::text[]
      )
    into v_blocked_codes
    from pg_catalog.jsonb_array_elements(
      v_actor_wide_denies
    ) as item(value);

    if v_combination_outcome <>
         'ALLOW' then
      v_blocked_codes :=
        v_blocked_codes ||
        v_base_reasons ||
        v_operational_reasons;
    end if;

    v_blocked_codes :=
      v_blocked_codes ||
      v_device_reasons;

    if pg_catalog.cardinality(
         v_blocked_codes
       ) = 0 then

      if v_requirement =
           'OPERATIONAL_ONLY' then
        v_blocked_codes :=
          array[
            'AUTH_OPERATIONAL_PERMISSION_DENIED'
          ]::text[];
      else
        v_blocked_codes :=
          array[
            'AUTH_ADMIN_PERMISSION_DENIED'
          ]::text[];
      end if;
    end if;

    select
      coalesce(
        pg_catalog.array_agg(
          distinct code
          order by code
        ),
        '{}'::text[]
      )
    into v_blocked_codes
    from pg_catalog.unnest(
      v_blocked_codes
    ) as reason(code);

  else
    v_blocked_codes :=
      '{}'::text[];
  end if;

  v_context_fingerprint :=
    'sha256:' ||
    pg_catalog.encode(
      extensions.digest(
        app_private.canonicalize_authorization_payload(
          p_access_context
        ),
        'sha256'
      ),
      'hex'
    );

  v_request_fingerprint :=
    'sha256:' ||
    pg_catalog.encode(
      extensions.digest(
        app_private.canonicalize_authorization_payload(
          v_request
        ),
        'sha256'
      ),
      'hex'
    );

  return pg_catalog.jsonb_build_object(
    'contract_family',
    'vento.authorization.response-contracts',
    'contract_family_version',
    '1.0.0',
    'contract_name',
    'AuthorizationDecision',
    'contract_version',
    '1.0.0',
    'schema_version',
    '1.0.0',
    'decision_id',
    p_decision_id::text,
    'decided_at',
    pg_catalog.to_char(
      p_decided_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'correlation_id',
    p_validated_request -> 'correlation_id',
    'access_context_ref',
    pg_catalog.jsonb_build_object(
      'context_id',
      p_access_context ->> 'context_id',
      'context_contract_version',
      p_access_context ->> 'contract_version',
      'resolved_at',
      p_access_context ->> 'resolved_at',
      'actor_type',
      p_access_context #>>
        '{actor_effective,actor_type}',
      'actor_id',
      p_access_context #>>
        '{actor_effective,actor_id}',
      'principal_type',
      p_access_context #>>
        '{principal,principal_type}',
      'principal_id',
      p_access_context #>>
        '{principal,auth_user_id}',
      'context_fingerprint',
      v_context_fingerprint
    ),
    'request',
    v_request,
    'permission_contract',
    v_permission,
    'resource',
    v_resource,
    'required_lanes',
    pg_catalog.to_jsonb(
      v_required_lanes
    ),
    'base_decision',
    v_base_decision,
    'operational_decision',
    v_operational_decision,
    'prerequisite_decisions',
    v_prerequisite_decisions,
    'device_decision',
    v_device_decision,
    'sensitivity_decision',
    v_sensitivity_decision,
    'field_policy_decision',
    v_field_policy_decision,
    'matched_allows',
    v_matched_allows,
    'matched_denies',
    v_matched_denies,
    'structural_denies',
    v_structural_denies,
    'actor_wide_denies',
    v_actor_wide_denies,
    'lane_denies',
    v_lane_denies,
    'blocked_reasons',
    pg_catalog.to_jsonb(
      v_blocked_codes
    ),
    'combination',
    pg_catalog.jsonb_build_object(
      'authorization_requirement',
      v_requirement,
      'outcome',
      v_combination_outcome
    ),
    'final_decision',
    v_final_decision,
    'audit',
    pg_catalog.jsonb_build_object(
      'request_fingerprint',
      v_request_fingerprint,
      'context_fingerprint',
      v_context_fingerprint,
      'permission_contract_fingerprint',
      v_permission ->>
        'contract_fingerprint',
      'resource_fingerprint',
      v_resource ->>
        'resource_fingerprint',
      'contract_release_hash',
      'sha256:9e8d1d7452ed5844fa76b9c718e7bb82ae029d6031234b3b6d9a17f22c2a4359',
      'identity_registry_sha256',
      'sha256:2f19d2ebabcc87f8a6bb8029da8f87e05ea86c9acb027aec134995d338604bf4',
      'dataset_evidence',
      coalesce(
        v_datasets ->
          'dataset_evidence',
        '[]'::jsonb
      ),
      'request_source',
      v_request_source
    )
  );
end
$auth_db_034_core$;

create or replace function
  app_private.project_safe_authorization_decision(
    p_decision jsonb
  )
returns jsonb
language plpgsql
immutable
strict
set search_path = pg_catalog, app_private
as $auth_db_034_safe_projection$
begin
  if p_decision ->> 'contract_family'
       <> 'vento.authorization.response-contracts'
     or p_decision ->> 'contract_name'
       <> 'AuthorizationDecision'
     or p_decision ->> 'contract_version'
       <> '1.0.0'
     or p_decision ->> 'final_decision'
       not in (
         'ALLOW',
         'DENY'
       ) then
    raise exception using
      errcode = '22023',
      message = 'AUTH_DB_034_SAFE_PROJECTION_INPUT_INVALID';
  end if;

  return pg_catalog.jsonb_build_object(
    'outcome',
    p_decision ->>
      'final_decision',
    'app_code',
    p_decision #>>
      '{request,app_code}',
    'permission_key',
    p_decision #>>
      '{request,permission_key}',
    'operation_kind',
    p_decision #>>
      '{request,operation_kind}',
    'resource_type',
    p_decision #>>
      '{resource,resource_type}',
    'safe_resource_reference',
    p_decision #>
      '{resource,safe_resource_reference}',
    'safe_message_code',
    case
      when p_decision ->>
             'final_decision'
           = 'ALLOW'
      then null
      else p_decision #>>
             '{blocked_reasons,0}'
    end,
    'safe_reason_codes',
    coalesce(
      p_decision ->
        'blocked_reasons',
      '[]'::jsonb
    ),
    'recovery_actions',
    '[]'::jsonb,
    'visible_fields',
    coalesce(
      p_decision #>
        '{field_policy_decision,visible_fields}',
      '[]'::jsonb
    ),
    'correlation_id',
    p_decision ->
      'correlation_id',
    'decided_at',
    p_decision ->
      'decided_at'
  );
end
$auth_db_034_safe_projection$;

create or replace function
  app_private.evaluate_authorization(
    p_evaluation_request jsonb
  )
returns jsonb
language plpgsql
volatile
security definer
set search_path = pg_catalog, app_private
as $auth_db_034_evaluate$
declare
  v_validated jsonb;
  v_context jsonb;
  v_app_code text;
  v_decision_id uuid;
  v_decided_at timestamptz;
begin
  v_validated :=
    app_private.validate_authorization_evaluation_request(
      p_evaluation_request
    );

  v_app_code :=
    v_validated #>>
      '{request,app_code}';

  v_context :=
    app_private.get_access_context(
      v_app_code
    );

  v_decision_id :=
    extensions.gen_random_uuid();

  v_decided_at :=
    pg_catalog.statement_timestamp();

  return app_private.evaluate_authorization_core(
    v_validated,
    v_context,
    v_decision_id,
    v_decided_at,
    '{}'::text[],
    0
  );
end
$auth_db_034_evaluate$;

create or replace function
  app_private.authorization_policy_allows(
    p_evaluation_request jsonb
  )
returns boolean
language sql
volatile
security definer
set search_path = pg_catalog, app_private
as $auth_db_034_policy$
  select
    app_private.evaluate_authorization(
      p_evaluation_request
    ) ->> 'final_decision'
      = 'ALLOW';
$auth_db_034_policy$;

create or replace function
  api.get_safe_authorization_decision(
    p_evaluation_request jsonb
  )
returns jsonb
language sql
volatile
security definer
set search_path = pg_catalog, app_private
as $auth_db_034_api_safe$
  select
    app_private.project_safe_authorization_decision(
      app_private.evaluate_authorization(
        p_evaluation_request
      )
    );
$auth_db_034_api_safe$;

revoke all
on function
  app_private.canonicalize_authorization_payload(jsonb),
  app_private.validate_authorization_evaluation_request(jsonb),
  app_private.resolve_permission_contract_snapshot(text, text),
  app_private.resolve_authorization_resource(text, jsonb, text, text[]),
  app_private.load_authorization_datasets(jsonb, jsonb, jsonb),
  app_private.evaluate_authorization_core(jsonb, jsonb, uuid, timestamptz, text[], integer),
  app_private.evaluate_authorization(jsonb),
  app_private.project_safe_authorization_decision(jsonb),
  app_private.authorization_policy_allows(jsonb)
from public, anon, authenticated, service_role;

revoke all
on function
  api.get_safe_authorization_decision(jsonb)
from public, anon, authenticated, service_role;

-- AUTH-DB-034 governed migration/test administrator.
-- Mirrors the AUTH-DB-033 posture: postgres may inspect and test the
-- private graph explicitly, while runtime roles remain revoked.
grant execute
on function
  app_private.canonicalize_authorization_payload(jsonb),
  app_private.validate_authorization_evaluation_request(jsonb),
  app_private.resolve_permission_contract_snapshot(text, text),
  app_private.resolve_authorization_resource(text, jsonb, text, text[]),
  app_private.load_authorization_datasets(jsonb, jsonb, jsonb),
  app_private.evaluate_authorization_core(jsonb, jsonb, uuid, timestamptz, text[], integer),
  app_private.evaluate_authorization(jsonb),
  app_private.project_safe_authorization_decision(jsonb),
  app_private.authorization_policy_allows(jsonb)
to postgres;

-- AUTH-DB-034 governed migration/test table administrator.
-- postgres is the governed local migration/test administrator only.
-- No runtime-client table privilege is introduced.
grant select
on table
  app_private.authorization_contract_releases,
  app_private.authorization_permission_contracts,
  app_private.authorization_resource_resolver_registry,
  app_private.authorization_dataset_source_registry,
  app_private.authorization_base_role_grants,
  app_private.authorization_operational_role_grants,
  app_private.authorization_dataset_seed_records
to postgres;

grant insert, delete
on table
  app_private.authorization_dataset_seed_records
to postgres;

grant update
on table
  app_private.authorization_permission_contracts
to postgres;

grant execute
on function
  api.get_safe_authorization_decision(jsonb)
to authenticated;

do $auth_db_034_projection_validation$
declare
  v_permission_count integer;
  v_resource_count integer;
  v_unresolved_ids integer;
  v_base_count integer;
  v_operational_count integer;
  v_dataset_count integer;
begin
  select permission_count
  into v_permission_count
  from
    app_private.authorization_contract_releases
  where catalog_id =
        'vento.authorization'
    and catalog_version =
        '1.1.0';

  select pg_catalog.count(*)
  into v_resource_count
  from
    app_private.authorization_permission_contracts
  where catalog_id =
        'vento.authorization'
    and catalog_version =
        '1.1.0'
    and status =
        'ACTIVE';

  if v_resource_count <>
       v_permission_count then
    raise exception
      'AUTH_DB_034_PERMISSION_COUNT_MISMATCH expected=% actual=%',
      v_permission_count,
      v_resource_count;
  end if;

  select pg_catalog.count(*)
  into v_unresolved_ids
  from
    app_private.authorization_permission_contracts p
  left join
    app_private.authorization_resource_resolver_registry r
      on r.resource_contract_id =
         p.resource_contract_id
     and r.status =
         'ACTIVE'
  where p.catalog_id =
        'vento.authorization'
    and p.catalog_version =
        '1.1.0'
    and p.status =
        'ACTIVE'
    and r.resource_contract_id is null;

  if v_unresolved_ids <> 0 then
    raise exception
      'AUTH_DB_034_RESOURCE_CONTRACT_ID_UNRESOLVED count=%',
      v_unresolved_ids;
  end if;

  if exists (
    select 1
    from
      app_private.authorization_permission_contracts
    where catalog_id =
          'vento.authorization'
      and catalog_version =
          '1.1.0'
      and (
        contract_fingerprint
          !~ '^sha256:[0-9a-f]{64}$'
        or source_manifest_sha256
          <> 'sha256:9e8d1d7452ed5844fa76b9c718e7bb82ae029d6031234b3b6d9a17f22c2a4359'
      )
  ) then
    raise exception
      'AUTH_DB_034_PERMISSION_FINGERPRINT_INVALID';
  end if;

  select pg_catalog.count(*)
  into v_base_count
  from
    app_private.authorization_base_role_grants
  where dataset_version =
        '1.1.0';

  if v_base_count <> 504 then
    raise exception
      'AUTH_DB_034_BASE_GRANT_COUNT_MISMATCH expected=504 actual=%',
      v_base_count;
  end if;

  select pg_catalog.count(*)
  into v_operational_count
  from
    app_private.authorization_operational_role_grants
  where dataset_version =
        '1.0.0';

  if v_operational_count <> 240 then
    raise exception
      'AUTH_DB_034_OPERATIONAL_GRANT_COUNT_MISMATCH expected=240 actual=%',
      v_operational_count;
  end if;

  select pg_catalog.count(*)
  into v_dataset_count
  from
    app_private.authorization_dataset_source_registry
  where status =
        'ACTIVE';

  if v_dataset_count <> 14 then
    raise exception
      'AUTH_DB_034_DATASET_REGISTRY_COUNT_MISMATCH expected=14 actual=%',
      v_dataset_count;
  end if;
end
$auth_db_034_projection_validation$;

reset role;

-- AUTH-DB-034 split-owner atomic activation.
--
-- Phase 1:
--   vento_authorization_owner owns and mutates the release registry.
--
-- Phase 2:
--   vento_context_freshness_owner owns the AUTH-DB-035 freshness
--   subsystem and emits the GLOBAL_AUTHORIZATION invalidation.
--
-- Phase 3:
--   vento_authorization_owner verifies the release invariant.
--
-- All phases remain inside the same migration transaction.

set local role vento_authorization_owner;

do $auth_db_034_activation_release$
declare
  v_already_active boolean;
begin
  perform pg_catalog.set_config(
    'vento.auth_db_034_activation_changed',
    'false',
    true
  );

  select
    status = 'ACTIVE'
  into v_already_active
  from
    app_private.authorization_contract_releases
  where catalog_id =
        'vento.authorization'
    and catalog_version =
        '1.1.0';

  if not found then
    raise exception
      'AUTH_DB_034_RELEASE_TO_ACTIVATE_MISSING';
  end if;

  if not coalesce(
       v_already_active,
       false
     ) then

    update
      app_private.authorization_contract_releases
    set
      status =
        'SUPERSEDED',
      retired_at =
        coalesce(
          retired_at,
          pg_catalog.statement_timestamp()
        )
    where catalog_id =
          'vento.authorization'
      and status =
          'ACTIVE'
      and catalog_version <>
          '1.1.0';

    update
      app_private.authorization_contract_releases
    set
      status =
        'ACTIVE',
      activated_at =
        coalesce(
          activated_at,
          pg_catalog.statement_timestamp()
        ),
      retired_at =
        null
    where catalog_id =
          'vento.authorization'
      and catalog_version =
          '1.1.0';

    if not found then
      raise exception
        'AUTH_DB_034_RELEASE_ACTIVATION_TARGET_MISSING';
    end if;

    perform pg_catalog.set_config(
      'vento.auth_db_034_activation_changed',
      'true',
      true
    );
  end if;
end
$auth_db_034_activation_release$;

reset role;

set local role vento_context_freshness_owner;

do $auth_db_034_activation_freshness$
begin
  if coalesce(
       pg_catalog.current_setting(
         'vento.auth_db_034_activation_changed',
         true
       ),
       'false'
     ) = 'true' then

    perform
      app_private.bump_context_freshness(
        pg_catalog.jsonb_build_object(
          'organization_id',
          app_private.resolve_organization_id(),
          'event_type',
          'CONTRACT_VERSION_CHANGED',
          'generation_scopes',
          pg_catalog.jsonb_build_array(
            'GLOBAL_AUTHORIZATION'
          ),
          'scope_ids',
          pg_catalog.jsonb_build_object(
            'GLOBAL_AUTHORIZATION',
            pg_catalog.jsonb_build_array(
              'GLOBAL'
            )
          ),
          'app_code',
          null,
          'subject_key_hash',
          null,
          'producer',
          'AUTH-DB-034::GLOBAL',
          'schema_version',
          '1.0.0'
        )
      );
  end if;
end
$auth_db_034_activation_freshness$;

reset role;

set local role vento_authorization_owner;

do $auth_db_034_activation_verify$
declare
  v_active_count integer;
  v_target_status text;
begin
  select pg_catalog.count(*)
  into v_active_count
  from
    app_private.authorization_contract_releases
  where catalog_id =
        'vento.authorization'
    and status =
        'ACTIVE';

  if v_active_count <> 1 then
    raise exception
      'AUTH_DB_034_ACTIVE_RELEASE_INVARIANT actual=%',
      v_active_count;
  end if;

  select status
  into v_target_status
  from
    app_private.authorization_contract_releases
  where catalog_id =
        'vento.authorization'
    and catalog_version =
        '1.1.0';

  if v_target_status <> 'ACTIVE' then
    raise exception
      'AUTH_DB_034_TARGET_RELEASE_NOT_ACTIVE status=%',
      v_target_status;
  end if;
end
$auth_db_034_activation_verify$;

reset role;


commit;
